using UnityEngine;
// Animated discharge uses the supplied eight-frame artwork and follows the hull's pipe.
public sealed class ShipPipeDischarge:MonoBehaviour {
 SpriteRenderer flow;Sprite[] frames;ShipController ship;ShipWaterPurification water;Rigidbody2D body;float clock,width,height;
 public bool FlowVisible=>flow&&flow.enabled;public Vector3 OutletPosition=>flow?flow.transform.position:transform.position;
 void Start(){ship=GetComponent<ShipController>();water=GetComponent<ShipWaterPurification>();body=GetComponent<Rigidbody2D>();var hull=GetComponentInChildren<SpriteRenderer>();float area=0;foreach(var r in GetComponentsInChildren<SpriteRenderer>())if(r.sprite&&!r.GetComponentInParent<Turret>()){float size=r.sprite.bounds.size.x*r.sprite.bounds.size.y*Mathf.Abs(r.transform.lossyScale.x*r.transform.lossyScale.y);if(size>area){hull=r;area=size;}if(r.sprite.name.ToLowerInvariant().Contains("gemi")||r.name=="Gemi"){hull=r;break;}}width=hull.sprite.bounds.size.x*Mathf.Abs(hull.transform.lossyScale.x);height=hull.sprite.bounds.size.y*Mathf.Abs(hull.transform.lossyScale.y);frames=new Sprite[8];for(int i=0;i<8;i++)frames[i]=Resources.Load<Sprite>("Voyage/pipe_flow_"+i);var go=new GameObject("Pipe waste outlet");go.transform.SetParent(transform,false);flow=go.AddComponent<SpriteRenderer>();flow.sortingOrder=90;flow.color=new Color(.68f,.8f,.69f,.75f);}
 void LateUpdate(){if(!flow)return;flow.enabled=StorySceneJourney.Instance.Stage!=JourneyStage.Finale&&water.NormalizedProgress<1&&ship.HasEnergy&&Vector2.Dot(body.linearVelocity,transform.up)>.15f;if(!flow.enabled)return;clock+=Time.deltaTime;flow.sprite=frames[(int)(clock*7)%frames.Length];flow.transform.position=transform.position+transform.right*(width*.20f)-transform.up*(height*.31f);flow.transform.rotation=transform.rotation;if(flow.sprite){var parent=transform.lossyScale;flow.transform.localScale=new Vector3(2.8f/flow.sprite.bounds.size.x/parent.x,5f/flow.sprite.bounds.size.y/parent.y,1);}}
}
